param([switch]$ExecutionAuthorized)
# One current project-main OFF regression. No reader, solver retry, build or next action.
$ErrorActionPreference='Stop';if(!$ExecutionAuthorized){throw 'Root full review and explicit -ExecutionAuthorized required'}
$tests=Split-Path -Parent $PSScriptRoot;$logs=Join-Path $tests 'logs';$tag='upl_column_public_off_r1';$folder=Join-Path $tests ('outputs\'+$tag);$record=Join-Path $logs ($tag+'.run.json');$callPath=Join-Path $logs ($tag+'.call.json');$log=Join-Path $logs ($tag+'.log')
function Need([bool]$ok,[string]$why){if(!$ok){throw $why}}
function E([string]$p){$f=Get-Item -LiteralPath $p -Force;[ordered]@{path=$f.FullName;bytes=[long]$f.Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}}
function J([string]$p){[IO.File]::ReadAllText($p)|ConvertFrom-Json}
function V($rows){foreach($r in $rows){Need ($r.path -and $null -ne $r.bytes -and $r.sha256) 'Missing bound Entry';$a=E $r.path;Need ($a.bytes -eq $r.bytes -and $a.sha256 -ieq $r.sha256) ('Changed bound artifact: '+$r.path)}}
function Fields($o,[string[]]$keys){foreach($key in $keys){Need ($null -ne $o.PSObject.Properties[$key] -and $null -ne $o.$key) ('Missing actual receipt property: '+$key)}}
function Same($a,$b){return ($a.path -ieq $b.path -and $a.bytes -eq $b.bytes -and $a.sha256 -ieq $b.sha256)}
function Fresh($paths){foreach($p in $paths){Need (!(Test-Path -LiteralPath $p)) ('Retained path protected: '+$p)}}
function Save([string]$p,$value){Fresh @($p);[IO.File]::WriteAllText($p,($value|ConvertTo-Json -Depth 18)+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)))}
Fresh @($folder,$record,$callPath,$log)
$bindings=@();$runtime=@();$baseline=@();$sourceBuild=$null;$sourceFreeze=$null;$program=$null;$oldCallEntry=$null;$oldInputsEntry=$null;$oldRunEntry=$null;$control=$null;$controlData=$null;$argv=@();$cwd=$null
try{
  $sourceBuild=E (Join-Path $logs 'upl_column_public_Release_r1.build.json');$b=J $sourceBuild.path;Fields $b @('source_freeze','inputs','tools','libraries','objects','project_main_object','project_call','isolated_GPU_program','runtime','canonical_programs_before','runtime_before')
  Need ($b.passed -and $b.stage -ceq 'upl_column_public_build_r1' -and $b.configuration -ceq 'Release' -and $b.status -ceq 'full_authoritative_GPU_Rebuild_passed_no_helper_or_program_run' -and $b.objects_exclude_main -and @($b.objects).Count -eq 110 -and @($b.runtime).Count -eq 4 -and $b.source_and_protected_artifacts_unchanged -and $b.canonical_programs_unchanged -and !$b.helper_built -and !$b.canonical_program_installed) 'Passed current authoritative Release project-main build required'
  V @($b.project_call,$b.source_freeze);$bc=J $b.project_call.path;Need ($bc.direct_native_call -and $bc.typed_LASTEXITCODE_captured_immediately -and $bc.owned_call_exited -and $bc.exit_code -is [int] -and $bc.exit_code -eq 0 -and !$bc.invocation_failure) 'Actual GPU project build owned typed exit0 required'
  $sourceFreeze=$b.source_freeze;$s=J $sourceFreeze.path;Fields $s @('source','current_source_snapshot','documentation_snapshot','canonical_programs_before','runtime_before');Need (@($s.source).Count -eq 265 -and @($s.current_source_snapshot).Count -eq 265 -and @($s.canonical_programs_before).Count -eq 7 -and @($s.runtime_before).Count -eq 4) 'Current265/doc/canonical7/runtime4 source closure required'
  $program=$b.isolated_GPU_program;$exeDir=Split-Path -Parent $program.path
  $bindings=@((E $PSCommandPath),(E (Join-Path $tests 'notes\upl_column_public_off_r1.json')),$sourceBuild,$sourceFreeze,$program,$b.project_main_object,$b.project_call,$bc.program,$bc.log)+@($b.inputs)+@($b.tools)+@($b.libraries)+@($b.objects)+@($s.source)+@($s.canonical_programs_before)+@($s.runtime_before)+@($s.documentation_snapshot.original,$s.documentation_snapshot.snapshot)
  foreach($row in $s.current_source_snapshot){Need ($row.original.bytes -eq $row.snapshot.bytes -and $row.original.sha256 -ieq $row.snapshot.sha256) 'Current source/snapshot differs';$bindings+=@($row.original,$row.snapshot)}
  foreach($row in $b.runtime){$sameRuntime=@($s.runtime_before|Where-Object {[IO.Path]::GetFileName($_.path) -ieq [IO.Path]::GetFileName($row.copy.path)});Need ($sameRuntime.Count -eq 1 -and $sameRuntime[0].bytes -eq $row.copy.bytes -and $sameRuntime[0].sha256 -ieq $row.copy.sha256 -and (Split-Path -Parent $row.copy.path) -ieq $exeDir) 'Existing current executable runtime differs';$runtime+=@($row);$bindings+=@($row.original,$row.copy)}
  # Historical receipts supply only exact argv, unchanged seed and immutable raw baseline.
  $oldCallEntry=E (Join-Path $logs 'upl_gpu_column_off_r1.call.json');$oldInputsEntry=E (Join-Path $logs 'upl_gpu_column_off_r1.inputs.json');$oldRunEntry=E (Join-Path $logs 'upl_gpu_column_off_r1.run.json')
  Need ($oldCallEntry.sha256 -ceq '8aea72f040c075aa060666586e3644c966c04196d659a86f1cf868910f5edd7c' -and $oldInputsEntry.sha256 -ceq '6a54ebb3dbcfcb04dcb268446411c722891dcd110aa1e92c10b044cb78458a30' -and $oldRunEntry.sha256 -ceq '9f114c372862b4ecdb8b3196b2ea294ac10400843bf06a443c7c0e97f281da82') 'Reviewed historical OFF receipts changed'
  $oc=J $oldCallEntry.path;$oi=J $oldInputsEntry.path;$orr=J $oldRunEntry.path;Fields $oc @('arguments','working_directory','program','log');Fields $oi @('arguments','input_prefix','runtime_XML','initial_files','retained_control','retained_control_data','bindings');Fields $orr @('call','input','files','completion','program')
  Need ($oc.direct_native_invocation -and $oc.typed_LASTEXITCODE_captured_immediately -and $oc.owned_call_exited -and $oc.exit_code -is [int] -and $oc.exit_code -eq 0 -and !$oc.invocation_failure -and $orr.passed -and $orr.source_input_runtime_canonical_unchanged -and (Same $orr.call $oldCallEntry) -and (Same $orr.input $oldInputsEntry) -and (Same $orr.program $oc.program)) 'Sealed historical OFF call/run ownership rejected'
  Need ($oi.expected_frames -eq 151 -and $oi.expected_steps -eq 15000 -and $oi.expected_native -eq 1040 -and $oi.dt_s -eq 1e-5 -and @($oc.arguments).Count -eq 11 -and @($oi.arguments).Count -eq 11) 'Unchanged OFF window/argv shape required'
  for($i=0;$i -lt 11;$i++){Need ($oc.arguments[$i] -ceq $oi.arguments[$i]) 'Historical actual argv differs from its inputs receipt'}
  $oldOut=Join-Path $tests 'outputs\upl_gpu_column_off_r1';Need ($oc.arguments[0] -ceq '-gpu' -and $oc.arguments[1] -ceq '-ompthreads:1' -and $oc.arguments[2] -ceq '-stable' -and $oc.arguments[3] -ceq '-mdbc' -and $oc.arguments[4] -ceq $oi.input_prefix -and $oc.arguments[5] -ceq $oldOut -and $oc.arguments[6] -ceq '-dirdataout' -and $oc.arguments[7] -ceq 'data' -and $oc.arguments[8] -ceq '-svres' -and $oc.arguments[9] -ceq '-svextraparts:1' -and $oc.arguments[10] -ceq '-nsteps:15000') 'Preserve exact accepted old-mDBC OFF physics and CLI'
  $prefix=Join-Path (Split-Path -Parent $oi.runtime_XML.path) ([IO.Path]::GetFileNameWithoutExtension($oi.runtime_XML.path));Need ([IO.Path]::GetExtension($oi.runtime_XML.path) -ceq '.xml' -and ($prefix+'.xml') -ceq $oi.runtime_XML.path -and $prefix -ceq $oi.input_prefix -and @($oi.initial_files).Count -eq 2) 'Exact retained OFF XML/seed prefix required'
  $seed=@($oi.initial_files|ForEach-Object {$_.copy});Need (@(Compare-Object (@(($prefix+'.bi4'),($prefix+'_Normals.nbi4'))|Sort-Object) ($seed.path|Sort-Object)).Count -eq 0) 'Exact retained BI4 and normals required'
  $control=$oi.retained_control;$controlData=$oi.retained_control_data;$baselineRoot=Split-Path -Parent $controlData;$baselinePrefix=$baselineRoot+[IO.Path]::DirectorySeparatorChar;$baseline=@($oi.bindings|Where-Object {$_.path.StartsWith($baselinePrefix,[StringComparison]::OrdinalIgnoreCase)})
  Need ((Split-Path -Leaf $baselineRoot) -ceq 'upl_gpu_public_explicit_off_r1' -and (Split-Path -Leaf $controlData) -ceq 'data' -and $baseline.Count -eq 310 -and @($baseline|Where-Object {[IO.Path]::GetFileName($_.path) -match '^Part_[0-9]{4}\.bi4$'}).Count -eq 151) 'Sealed explicit-OFF151-frame baseline required'
  $controlRecord=J $control.path;Need $controlRecord.passed 'Retained explicit-OFF control rejected'
  $bindings+=@($oldCallEntry,$oldInputsEntry,$oldRunEntry,$oc.program,$oc.log,$orr.completion,$oi.runtime_XML,$control)+$seed+@($orr.files)+$baseline
  $cwd=$oc.working_directory;Need ($cwd -ceq $oi.working_directory -and (Test-Path -LiteralPath $cwd -PathType Container)) 'Preserve actual historical working directory';$remaps=0
  foreach($a in $oc.arguments){if($a -ceq $oldOut){$argv+=$folder;$remaps++}else{$argv+=$a}};Need ($remaps -eq 1 -and $argv.Count -eq 11) 'Only one output-directory argument remap permitted'
  V $bindings
}catch{Save $record ([ordered]@{stage='upl_column_public_off_r1';passed=$false;phase='preflight';source_build=$sourceBuild;source_freeze=$sourceFreeze;program=$program;call=$null;inputs=$bindings;files=@();solver_started=$false;failure=$_.Exception.Message;historical_source_originals_revalidated_as_current=$false;physical_acceptance=$false});throw}
[IO.File]::WriteAllBytes($log,[byte[]]@());$started=[DateTime]::UtcNow.ToString('o');$code=$null;$launchFailure=$null;$saved=$ErrorActionPreference;Push-Location $cwd
try{$ErrorActionPreference='Continue';$global:LASTEXITCODE=$null;& $program.path @argv 2>&1|Tee-Object -FilePath $log -Append|Out-Host;$code=$LASTEXITCODE}catch{$launchFailure=$_.Exception.Message}finally{Pop-Location;$ErrorActionPreference=$saved}
Save $callPath ([ordered]@{program=$program;arguments=$argv;working_directory=$cwd;started_utc=$started;ended_utc=[DateTime]::UtcNow.ToString('o');direct_native_call=$true;typed_LASTEXITCODE_captured_immediately=($code -is [int]);owned_call_exited=($code -is [int]);exit_code=$code;invocation_failure=$launchFailure;log=(E $log);actual_solver_call=$true;project_main=$true;fixture_or_Run_override=$false;old_solver_rerun=$false;physical_acceptance=$false})
# Seal the original typed call before inspecting any new solver output.
$failure=$launchFailure;$unchanged=$false;$runOut=$null;$files=@();$frames=0;$sequence=$false
try{Need ($code -is [int] -and $code -eq 0 -and !$launchFailure) 'Owned current OFF project-main exit rejected';$runOut=E (Join-Path $folder 'Run.out');$raw=@(Get-ChildItem -LiteralPath (Join-Path $folder 'data') -File -Filter 'Part_*.bi4');$frames=$raw.Count;$expected=@(0..150|ForEach-Object {'Part_{0:D4}.bi4' -f $_});$sequence=($frames -eq 151 -and @(Compare-Object (@($raw.Name)|Sort-Object) ($expected|Sort-Object)).Count -eq 0);Need $sequence 'Require exactly Part_0000..0150; numerical read remains separate'}catch{$failure=$_.Exception.Message}
try{V $bindings;$unchanged=$true}catch{if(!$failure){$failure=$_.Exception.Message}}
