$passed=(!$failure -and $unchanged -and $sequence -and $null -ne $runOut -and $code -is [int] -and $code -eq 0)
Save $record ([ordered]@{stage='upl_column_public_off_r1';passed=[bool]$passed;phase='run_sealed_native_review_pending';source_build=$sourceBuild;source_freeze=$sourceFreeze;program=$program;retained_actual_call=$oldCallEntry;retained_input_manifest=$oldInputsEntry;retained_run=$oldRunEntry;retained_control=$control;retained_control_data=$controlData;retained_baseline_files=$baseline;arguments=$argv;working_directory=$cwd;exact_argument_output_remaps=1;input_runtime_XML=$oi.runtime_XML;initial_files=$seed;call=(E $callPath);run_out=$runOut;inputs=$bindings;runtime=$runtime;files=$files;expected_steps=15000;expected_samples=151;expected_native=1040;dt_s=1e-5;native_frames=$frames;native_frame_sequence_exact=$sequence;source_input_runtime_canonical_unchanged=$unchanged;source_inputs_objects_runtime_canonical_unchanged=$unchanged;all_raw_outputs_hash_bound=$true;fresh_solver_calls=1;old_solver_rerun=$false;inputs_copied_or_written=$false;historical_source_originals_revalidated_as_current=$false;native_exact_checked=$false;original15_clock_metadata_absence_compared=$false;reader_or_QC_started=$false;completed_steps_or_actual_end_verified_by_this_owner=$false;next_action_started=$false;failure=$failure;physical_acceptance=$false})
